    horizontal_tracks = sum(sum(v == 2 for v in grid[r]) for r in horizontal)
    vertical_tracks = sum(sum(grid[r][c] == 2 for r in range(h)) for c in vertical)
    use_vertical_tracks = vertical_tracks >= horizontal_tracks

