def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Long rows or columns of 2s are tracks.
    htracks = [r for r in range(h)
               if sum(grid[r][c] == 2 for c in range(w)) >= 0.6 * w]
    vtracks = [c for c in range(w)
               if sum(grid[r][c] == 2 for r in range(h)) >= 0.6 * h]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    vertical_tracks = len(vtracks) >= len(htracks)

    def paint_beam(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 1

    def paint_crossing(r, c):
        for rr in range(r - 1, r + 2):
            for cc in range(c - 1, c + 2):
                if 0 <= rr < h and 0 <= cc < w and (rr, cc) != (r, c):
                    if out[rr][cc] != 3:
                        out[rr][cc] = 1

    for r, c in centers:
        if vertical_tracks:
            # Beam runs horizontally, crossing the vertical tracks.
            for cc in range(w):
                paint_beam(r, cc)
            for track_c in vtracks:
                if grid[r][track_c] == 2:
                    paint_crossing(r, track_c)
        else:
            # Beam runs vertically, crossing the horizontal tracks.
            for rr in range(h):
                paint_beam(rr, c)
            for track_r in htracks:
                if grid[track_r][c] == 2:
                    paint_crossing(track_r, c)

    return out
